// resolveServiceCtx resolves a service endpoint by querying ServiceHealthState for
// healthy instances. Retries with exponential backoff until found or ctx is cancelled.
func (sm *ServiceManager) resolveServiceCtx(ctx context.Context, serviceName string) (grpc.ClientConnInterface, error) {
	backoff := 2 * time.Second
	maxBackoff := 30 * time.Second
	for {
		conn := sm.sc.Conn()
		if conn == nil {
			return nil, fmt.Errorf("no active connection for service resolution")
		}
		token, err := sm.identity.GetToken()
		if err != nil {
			return nil, fmt.Errorf("failed to get token for service resolution: %w", err)
		}
		client := healthstate_pb.NewServiceHealthStateServiceClient(conn)
		rpcCtx := metadata.AppendToOutgoingContext(ctx, "authorization", "Bearer "+token)
		resp, err := client.GetAllInstances(rpcCtx, &healthstate_pb.InstancesGetAllRequest{})
		if err == nil {
			for _, health := range resp.Entries {
				if health.ServiceId == serviceName && health.Status == healthreport_pb.InstanceStatus_INSTANCE_STATUS_HEALTHY {
					if ep := health.GrpcEndpoint; ep != nil && ep.Host != "" && ep.Port > 0 {
						target := fmt.Sprintf("%s:%d", ep.Host, ep.Port)
						zap.L().Info("Resolved service endpoint via health entries",
							zap.String("service", serviceName),
							zap.String("endpoint", target))
						return sm.sc.CreateChannel(target)
					}
				}
			}
			zap.L().Warn("No healthy instance found for service, retrying",
				zap.String("service", serviceName),
				zap.Duration("retry_in", backoff))
		} else {
			if sm.ctx.Err() != nil {
				return nil, sm.ctx.Err()
			}
			zap.L().Warn("Failed to query ServiceHealthState, retrying",
				zap.String("service", serviceName),
				zap.Error(err),
				zap.Duration("retry_in", backoff))
		}
		select {
		case <-time.After(backoff):
		case <-sm.ctx.Done():
			return nil, sm.ctx.Err()
		case <-ctx.Done():
			return nil, fmt.Errorf("service %q not available: %w", serviceName, ctx.Err())
		}
		if backoff < maxBackoff {
			backoff *= 2
			if backoff > maxBackoff {
				backoff = maxBackoff
			}
		}
	}
}

